<?php
// Shared report presentation. All report queries remain read-only.
if(!function_exists('riEscape')){
function riEscape($value): string{return htmlspecialchars((string)($value??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function riGet(string $key,string $default=''): string{return is_string($_GET[$key]??null)?mb_substr(trim($_GET[$key]),0,150):$default;}
function riLike(string $value): string{return '%'.str_replace(['!','%','_'],['!!','!%','!_'],$value).'%';}
function riDate($value,string $format='M j, Y'): string{if(!$value)return 'Not recorded';$time=strtotime($value);return $time===false?'Not recorded':date($format,$time);}
function riURL(string $page,array $params=[]): string{return 'layout.php?'.http_build_query(array_filter(array_merge(['page'=>$page],$params),static fn($v)=>$v!==''&&$v!==null));}
function riPage(int $total): array{$pages=max(1,(int)ceil($total/10));$current=min($pages,max(1,(int)($_GET['p']??1)));return [$current,$pages,($current-1)*10];}
function riStart(string $page,string $title,string $description,string $scope): void {?>
<link rel="stylesheet" href="../assets/css/reports-insights.css?v=20261028-1"><section class="ri-root" data-report-page="<?=$page?>" aria-labelledby="riTitle"><header class="ri-heading"><div><p class="ri-eyebrow">REPORTS & INSIGHTS</p><h1 id="riTitle"><?=riEscape($title)?></h1><p><?=riEscape($description)?></p></div><span class="ri-scope"><i class="far fa-calendar" aria-hidden="true"></i><?=riEscape($scope)?></span></header><nav class="ri-report-nav" aria-label="Reports"><?php foreach(['reports'=>['Overview','fa-chart-simple'],'examinee_reports'=>['Examinees','fa-user-check'],'ses_analytics'=>['SES analytics','fa-chart-pie'],'olsat_reports'=>['OLSAT results','fa-clipboard-list'],'counseling_reports'=>['Counseling','fa-comments']] as $key=>[$label,$icon]):?><a href="<?=riURL($key)?>" <?=$page===$key?'aria-current="page"':''?>><i class="fas <?=$icon?>" aria-hidden="true"></i><?=riEscape($label)?></a><?php endforeach;?></nav>
<?php }
function riEnd(array $charts=[]): void {?></section><script type="application/json" id="riChartData"><?=json_encode($charts,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_INVALID_UTF8_SUBSTITUTE)?></script><script src="../assets/js/reports-insights.js?v=20261028-2"></script><?php }
function riCard(string $label,$value,string $hint,string $tone='blue',?string $url=null,bool $selected=false): void { $tag=$url?'a':'div';?><<?=$tag?> class="ri-stat" data-tone="<?=riEscape($tone)?>" <?=$url?'href="'.riEscape($url).'"':''?> <?=$selected?'aria-current="true"':''?>><span class="ri-stat-label"><?=riEscape($label)?></span><strong><?=riEscape($value)?></strong><small><?=riEscape($hint)?></small><?php if($url):?><i class="fas fa-arrow-right" aria-hidden="true"></i><?php endif;?></<?=$tag?>><?php }
function riChart(string $id,string $title,string $hint,array $labels,array $values,string $kind='bar',array $colors=[]): array { $has=array_sum($values)>0;?><article class="ri-panel"><header class="ri-panel-heading"><div><h2><?=riEscape($title)?></h2><p><?=riEscape($hint)?></p></div></header><?php if($has):?><div class="ri-chart <?=in_array($kind,['doughnut','pie'],true)?'ri-chart-round':''?>"><canvas id="<?=$id?>" role="img" aria-label="<?=riEscape($title)?>"></canvas></div><p class="ri-chart-unavailable" hidden>Chart unavailable. The values are listed below.</p><details class="ri-chart-values"><summary>View chart values</summary><ul><?php foreach($labels as $i=>$label):?><li><span><?=riEscape($label)?></span><strong><?=(int)($values[$i]??0)?></strong></li><?php endforeach;?></ul></details><?php else:?><div class="ri-chart-empty"><i class="fas fa-chart-bar" aria-hidden="true"></i><strong>No data for this chart</strong><p>Values will appear when matching records are available.</p></div><?php endif;?></article><?php return ['id'=>$id,'kind'=>$kind,'labels'=>$labels,'values'=>$values,'colors'=>$colors]; }
function riPagination(string $page,array $params,int $total,int $current,int $pages): void { ?><footer class="ri-pagination"><span><?=$total?'Showing '.(($current-1)*10+1).'–'.min($current*10,$total).' of '.$total.' records':'0 matching records'?></span><nav aria-label="Report pages"><?php if($current>1):?><a class="ri-button" rel="prev" href="<?=riEscape(riURL($page,array_merge($params,['p'=>$current-1])))?>">Previous</a><?php else:?><button class="ri-button" disabled>Previous</button><?php endif;?><span>Page <?=$current?> of <?=$pages?></span><?php if($current<$pages):?><a class="ri-button" rel="next" href="<?=riEscape(riURL($page,array_merge($params,['p'=>$current+1])))?>">Next</a><?php else:?><button class="ri-button" disabled>Next</button><?php endif;?></nav></footer><?php }
function riError(string $message): void{if($message!==''){?><p class="ri-error" role="alert"><?=riEscape($message)?></p><?php }}
}
